interface.definition:
a!localVariables(
  local!userBU: a!refreshVariable(
    value: union(
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      ),
      reject(
        fn!isnull,
        #"SYSTEM_SYSRULES_forEach"(
          items: getgroupsformemberuser(user: loggedInUser()),
          expression: {
            a!localVariables(
              local!groupName: group(fv!item, "groupName"),
              local!list: split(local!groupName, " "),
              local!length: length(local!list),
              if(
                and(
                  local!length > 2,
                  contains(local!list, "CAW"),
                  or(
                    contains(local!list, "BUPPP"),
                    contains(local!list, "BUPIC"),
                    contains(local!list, "BUPPP_BUPIC"),
                    contains(local!list, "BUCos"),
                    contains(local!list, "CoS/Delegate")
                  )
                ),
                joinarray(
                  remove(local!list, { 1, local!length }),
                  " "
                ),
                null
              )
            )
          }
        )
      )
    ),
    refreshAlways: true
  ),
  local!ismemberofusergroup:or(
    contains(
      touniformstring(local!userBU),
      tostring(ri!nomination.originatingBU)
    ),
    contains(
      touniformstring(local!userBU),
      tostring(ri!nomination.returnBU)
    ),
    a!isNullOrEmpty(local!userBU)),
    if(
      local!ismemberofusergroup,
#"SYSTEM_SYSRULES_gridField_v1"(
  label: "ASK Audit",
  labelPosition: "COLLAPSED",
  data: ri!audit,
  pageSize: 15,
  emptyGridMessage: "No Audit History Found",
  columns: {
    #"SYSTEM_SYSRULES_gridColumn"(
      label: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442087",
      sortField: "action",
      value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
        value: fv!row.action
      )
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3441339",
      sortField: "createdBy",
      value: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(fv!row.createdBy)
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442081",
      sortField: "createdOn",
      value: fv!row.createdOn
    ),
    #"SYSTEM_SYSRULES_gridColumn"(
      label: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442093",
      showWhen: ri!moduleTypeID <> #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164394",
      sortField: "description",
      value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
        value: fv!row.description 
      )
    )
  },
  initialSorts: #"SYSTEM_SYSRULES_sortInfo"(
      field: "createdOn"
    ),
  /*spacing: "DENSE",*/
  shadeAlternateRows: true,
  rowHeader: 1
),
#"SYSTEM_SYSRULES_sectionLayout_v1"(
  contents: #"SYSTEM_SYSRULES_cardLayout"(
    contents: #"SYSTEM_SYSRULES_richTextDisplayField"(
      value: #"SYSTEM_SYSRULES_richTextItem_v1"(
        text: "You are not able to view this nomination because you are not a part of the  " & touniformstring(ri!nomination.originatingBU) &" Group", 
        style: "STRONG",
        size: "MEDIUM",

      )
    )
  )
),

    )
)
